{
  "pipeline_id": "quality-control",
  "name": "Quality Control + Adapter Trimming",
  "description": "Lightweight QC pipeline for raw sequencing reads. Runs FastQC to assess read quality metrics (base quality, adapter content, GC bias, duplication) followed by Trimmomatic to remove adapters and low-quality bases. Generates a clean FASTQ ready for downstream alignment. Use this as a standalone QC check or as the entry point before any alignment-based pipeline.",
  "estimated_duration": "15-45 minutes",
  "inputs": [
    {
      "name": "inputFastqR1",
      "type": "file",
      "required": true,
      "description": "Read 1 FASTQ file (.fastq.gz)"
    },
    {
      "name": "inputFastqR2",
      "type": "file",
      "required": true,
      "description": "Read 2 FASTQ file (.fastq.gz) — omit for single-end data"
    },
    {
      "name": "sampleName",
      "type": "string",
      "required": false,
      "default": "sample",
      "description": "Sample identifier"
    },
    {
      "name": "readType",
      "type": "select",
      "required": false,
      "default": "paired-end",
      "options": [
        "paired-end",
        "single-end"
      ],
      "description": "Sequencing layout"
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "fastqc",
      "description": "Assess raw read quality for both mates — quality scores, adapter content, duplication rates"
    },
    {
      "step": 2,
      "tool": "trimmomatic",
      "description": "Remove adapters, low-quality leading/trailing bases, and short reads below minimum length",
      "after": [
        "step1_fastqc"
      ]
    },
    {
      "step": 3,
      "tool": "fastqc",
      "description": "Post-trimming QC on both mates — verify adapter removal and quality improvement",
      "after": [
        "step2_trim"
      ]
    }
  ]
}

